WITH matched_keys AS (SELECT city FROM suppliers EXCEPT ALL SELECT city FROM suppliers WHERE city IS NOT NULL), reconciled AS (SELECT s.* FROM suppliers s JOIN matched_keys k ON s.city = k.city) SELECT CASE WHEN rating >= 3.9 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, COUNT(CASE WHEN city = 'Berlin' THEN 1 END) AS berlin_count, SIZE(COLLECT_SET(city)) AS num_cities, SUM(CASE WHEN country = 'TH' THEN rating ELSE 0 END) AS th_rating FROM reconciled GROUP BY rating_tier ORDER BY num_cities NULLS FIRST
